package com.yeyamo_mobile.api.partner_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.yeyamo_mobile.api.partner_service.application.port.PartnerOutboxPort;import com.yeyamo_mobile.api.partner_service.domain.model.*;import com.yeyamo_mobile.api.partner_service.infrastructure.persistence.*;import com.yeyamo_mobile.api.partner_service.infrastructure.persistence.ArtisanRepositories.*;import com.yeyamo_mobile.api.partner_service.interfaces.rest.ArtisanDtos;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class)class ArtisanProfileServiceTest{@Mock Profiles profiles;@Mock Specialties specialties;@Mock SpringPartnerRepository partners;@Mock SpringPartnerDocumentRepository documents;@Mock KycRequirements requirements;@Mock PartnerOutboxPort outbox;ArtisanProfileService service;UUID partnerId;PartnerEntity partner;@BeforeEach void setUp(){service=new ArtisanProfileService(profiles,specialties,partners,documents,requirements,outbox);partnerId=UUID.randomUUID();partner=mock(PartnerEntity.class);lenient().when(partner.getId()).thenReturn(partnerId);lenient().when(partners.findByOwnerUserId("owner")).thenReturn(Optional.of(partner));}
 @Test void rejectsDuplicateProfile(){when(profiles.existsById(partnerId)).thenReturn(true);PartnerException error=assertThrows(PartnerException.class,()->service.create("owner",request(),"cid"));assertEquals("ARTISAN_PROFILE_EXISTS",error.getCode());verify(outbox,never()).append(any(),any(),any(),any(),any());}
 @Test void createsProfileAndEvent(){UUID specialtyId=request().specialtyIds().iterator().next();ArtisanSpecialtyEntity specialty=mock(ArtisanSpecialtyEntity.class);when(specialty.getId()).thenReturn(specialtyId);when(specialty.getName()).thenReturn("Sculpture");when(specialties.findByIdInAndActiveTrue(any())).thenReturn(List.of(specialty));when(profiles.save(any())).thenAnswer(inv->inv.getArgument(0));ArtisanDtos.Response response=service.create("owner",request(),"cid");assertEquals(partnerId,response.partnerId());verify(outbox).append(eq("ArtisanProfileCreated"),eq(partnerId),eq("owner"),eq("cid"),any());}
 @Test void enforcesConfiguredKycBeforeVerification(){ArtisanProfileEntity profile=ArtisanProfileEntity.create(partnerId,"Artisan","Story","Craft",5,"CM",null,null,null,Set.of("fr-CM"),Set.of(),true,false);profile.verification(ArtisanProfileEntity.VerificationStatus.PENDING);when(profiles.findById(partnerId)).thenReturn(Optional.of(profile));when(partners.findById(partnerId)).thenReturn(Optional.of(partner));when(partner.getBusinessType()).thenReturn(BusinessType.ARTISAN);ArtisanKycRequirementEntity requirement=mock(ArtisanKycRequirementEntity.class);when(requirement.getDocumentType()).thenReturn(DocumentType.PORTFOLIO);when(requirements.findByCountryCodeAndPartnerTypeAndRequiredTrue("CM",BusinessType.ARTISAN)).thenReturn(List.of(requirement));PartnerException error=assertThrows(PartnerException.class,()->service.verify(partnerId,new ArtisanDtos.VerificationRequest(ArtisanProfileEntity.VerificationStatus.VERIFIED,"ok"),"admin","cid"));assertEquals("ARTISAN_KYC_INCOMPLETE",error.getCode());}
 private ArtisanDtos.Request request(){return new ArtisanDtos.Request("Artisan","Story","Craft",5,"CM",null,null,null,Set.of("fr-CM"),Set.of(UUID.fromString("20000000-0000-0000-0000-000000000001")),true,false,BusinessType.ARTISAN);}}
